using SharpTestBench;
using Xunit;
public sealed partial class ScopeCrossTests
{
    [Fact] public void S031_RecursiveSamplingRollsBackAndRecovers()
    {CoveragePoint<int>? point=null;bool recurse=true;CoverageBin<int>[][] axes=[[B("a",value=>{if(recurse)point!.Sample(value);return true;})],[B("b",_=>true)],[B("c",_=>true)]];point=new FunctionalCoverage().AddCross("recursive",axes);Assert.Throws<InvalidOperationException>(()=>point.Sample(1));Assert.Equal(0UL,point.Snapshot().Samples);Assert.All(point.Snapshot().Bins,b=>Assert.Equal(0UL,b.Hits));recurse=false;point.Sample(2);Assert.Equal(1UL,point.Snapshot().Samples);Assert.Equal(100,point.Snapshot().Percent);}
    [Fact] public void S032_ActiveSuiteResetCannotClearEarlierOrdinaryPoint()
    {var c=new FunctionalCoverage();var earlier=c.AddPoint("earlier",new CoverageBin<int>("all",_=>true));earlier.Sample(1);bool clear=false;CoverageBin<int>[][] axes=[[B("a",_=>{if(clear)c.Reset();return true;})],[B("b",_=>true)],[B("c",_=>true)]];var p=c.AddCross("active",axes);p.Sample(1);clear=true;Assert.Throws<InvalidOperationException>(()=>p.Sample(2));Assert.Equal(1UL,earlier.Snapshot().Samples);Assert.Equal(1UL,p.Snapshot().Samples);clear=false;p.Sample(3);Assert.Equal(2UL,p.Snapshot().Samples);Assert.Equal(1UL,earlier.Snapshot().Bins[0].Hits);}
    [Fact] public void S033_ClassifierSnapshotSeesOnlyCommittedCounters()
    {CoveragePoint<int>? point=null;var seen=new List<ulong>();CoverageBin<int>[][] axes=[[B("a",_=>{seen.Add(point!.Snapshot().Samples);return true;})],[B("b",_=>true)],[B("c",_=>true)]];point=new FunctionalCoverage().AddCross("observed",axes);point.Sample(1);point.Sample(2);Assert.Equal(new ulong[]{0,1},seen);Assert.Equal(2UL,point.Snapshot().Samples);Assert.Equal(2UL,point.Snapshot().Bins[0].Hits);}
    [Fact] public void S034_ResetRetainsRankGoalAndExcludedCellDefinitions()
    {var p=new FunctionalCoverage().AddCross("reset",Axes(3),goal:2,excluded:[["one","one","one"]]);p.Sample(0);p.Sample(0);p.Sample(7);string[] names=p.Snapshot().Bins.Select(b=>b.Name).ToArray();p.Reset();Assert.Equal(0UL,p.Snapshot().Samples);Assert.Equal(0UL,p.Snapshot().Unmatched);Assert.Equal(names,p.Snapshot().Bins.Select(b=>b.Name));Assert.All(p.Snapshot().Bins,b=>{Assert.Equal(0UL,b.Hits);Assert.Equal(2UL,b.Goal);});p.Sample(0);Assert.Equal(0,p.Snapshot().Percent);p.Sample(0);Assert.Equal(100d/7,p.Snapshot().Percent);}
    [Fact] public void S035_MergeMapsReorderedAxisBinsByCellIdentity()
    {var first=new FunctionalCoverage();var p=first.AddCross("merge",Axes(3));p.Sample(0);var second=new FunctionalCoverage();var axes=Axes(3);foreach(var axis in axes)Array.Reverse(axis);var q=second.AddCross("merge",axes);q.Sample(7);first.Merge(second.Snapshot());Assert.Equal(2UL,p.Snapshot().Samples);Assert.Equal(1UL,p.Snapshot().Bins.Single(b=>b.Name=="4:zero4:zero4:zero").Hits);Assert.Equal(1UL,p.Snapshot().Bins.Single(b=>b.Name=="3:one3:one3:one").Hits);Assert.Equal(2UL,p.Snapshot().Bins.Aggregate(0UL,(sum,b)=>sum+b.Hits));}
    [Fact] public void S036_NewTwoAxisSharedSampleCrossMergesLegacyTupleSnapshots()
    {CoverageBin<int>[] bins=[B("zero",x=>x==0),B("one",x=>x==1)];var legacy=new FunctionalCoverage();var old=legacy.AddCross("same",bins,bins);old.Sample((1,0));CoverageBin<(int Left,int Right)>[][] axes=[[new("zero",x=>x.Left==0),new("one",x=>x.Left==1)],[new("zero",x=>x.Right==0),new("one",x=>x.Right==1)]];var current=new FunctionalCoverage();var point=current.AddCross("same",axes);point.Sample((0,1));current.Merge(legacy.Snapshot());Assert.Equal(2UL,point.Snapshot().Samples);Assert.Equal(50,point.Snapshot().Percent);Assert.Equal(1UL,point.Snapshot().Bins.Single(b=>b.Name=="4:zero3:one").Hits);Assert.Equal(1UL,point.Snapshot().Bins.Single(b=>b.Name=="3:one4:zero").Hits);}
    [Fact] public void S037_RankMismatchMergeCannotPartiallyUpdateEarlierPoint()
    {var target=new FunctionalCoverage();var first=target.AddPoint("first",new CoverageBin<int>("all",_=>true));first.Sample(1);CoverageBin<int>[][] axes=[[B("a",_=>true)],[B("b",_=>true)],[B("c",_=>true)]];var last=target.AddCross("last",axes);last.Sample(1);var source=new FunctionalCoverage();source.AddPoint("first",new CoverageBin<int>("all",_=>true)).Sample(1);source.AddCross("last",new[]{new[]{B("a",_=>true)}}).Sample(1);Assert.Throws<ArgumentException>(()=>target.Merge(source.Snapshot()));Assert.Equal(1UL,first.Snapshot().Samples);Assert.Equal(1UL,last.Snapshot().Samples);Assert.Equal(1UL,last.Snapshot().Bins[0].Hits);}
    [Fact] public void S038_OverflowMergeIsAtomicForFeasibleOverlappingCrossState()
    {var c=new FunctionalCoverage();var first=c.AddPoint("first",new CoverageBin<int>("all",_=>true));first.Sample(0);var axes=Enumerable.Range(0,3).Select(_=>new[]{B("a",_=>true),B("b",_=>true)}).ToArray();var last=c.AddCross("last",axes);last.Sample(0);var incoming=new CoverageSnapshot([new("first",1,0,[new("all",1,1)]),new("last",ulong.MaxValue,0,last.Snapshot().Bins.Select(b=>new CoverageBinSnapshot(b.Name,ulong.MaxValue,b.Goal)).ToArray())]);Assert.Throws<OverflowException>(()=>c.Merge(incoming));Assert.Equal(1UL,first.Snapshot().Samples);Assert.Equal(1UL,last.Snapshot().Samples);Assert.All(last.Snapshot().Bins,b=>Assert.Equal(1UL,b.Hits));}
    [Fact] public void S039_CombinedPercentageWeightsAllGeneratedBins()
    {var c=new FunctionalCoverage();var cross=c.AddCross("cross",Axes(3));var ordinary=c.AddPoint("ordinary",new CoverageBin<int>("seen",_=>true));cross.Sample(0);ordinary.Sample(0);Assert.Equal(12.5,cross.Snapshot().Percent);Assert.Equal(100d*2/9,c.Snapshot().Percent!.Value);}
    [Fact] public void S040_NamedArgumentsAndTypedDefaultsRetainBothOverloads()
    {var c=new FunctionalCoverage();Assert.Equal("axes",Assert.Throws<ArgumentNullException>(()=>c.AddCross<int>("null",default!,excluded:default!)).ParamName);CoverageBin<int>[] bins=[B("all",_=>true)];var legacy=c.AddCross(name:"tuple",left:bins,right:bins,maximumBins:1,excluded:[]);var shared=c.AddCross(name:"axes",axes:Axes(1),maximumBins:2,excluded:[]);legacy.Sample((1,2));shared.Sample(1);Assert.Equal(2,c.Snapshot().Points.Length);Assert.Equal(1UL,legacy.Snapshot().Samples);Assert.Equal(1UL,shared.Snapshot().Samples);Assert.Equal(50,shared.Snapshot().Percent);}
}
